WITH oracle_1 AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,lastPx/10000.0 AS px,MIN(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS lo,MAX(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS hi FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND CASE WHEN px IS NULL OR lo IS NULL OR hi IS NULL THEN NULL WHEN px<=lo THEN '最低' WHEN px>=hi THEN '最高' WHEN (px-lo)/NULLIF(hi-lo,0)<=0.25 THEN '低' WHEN (px-lo)/NULLIF(hi-lo,0)>=0.75 THEN '高' ELSE '中' END='最高'), branch_1 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_1 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode IN (0,1) AND q.volume>=0), oracle_2 AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,lowPx/10000.0 AS px,MIN(lowPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS extreme FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px<=extreme), branch_2 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_2 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=1 AND q.volume>=0) SELECT mktcode,tgtcode,bizdate FROM branch_1 UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM branch_2;
